-- Synthetic rule fixtures only; no real email and no plaintext OTP table storage.
begin;
set local statement_timeout='60s';
create temporary table fr33_results(test text,result text);
grant all on fr33_results to authenticated,anon;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin
 if ok is not true then raise exception 'FR33 assertion failed: %',label;end if;
 insert into fr33_results values(label,'PASS');
end $$;
create function pg_temp.denied(sql text,label text) returns void language plpgsql as $$ begin
 begin execute sql;exception when insufficient_privilege or check_violation then insert into fr33_results values(label,'PASS');return;end;
 raise exception 'FR33 forbidden operation succeeded: %',label;
end $$;
create function pg_temp.no_update(sql text,label text) returns void language plpgsql as $$ declare changed int;begin
 begin execute sql;get diagnostics changed=row_count;
 exception when insufficient_privilege or check_violation then changed:=0;end;
 perform pg_temp.assert(changed=0,label);
end $$;
do $$ declare who text; role_name text; identity uuid; id bigint; begin
 foreach who in array array['rider','other','customer','vendor','admin'] loop
  role_name:=case when who='other' then 'rider' else who end;identity:=gen_random_uuid();
  insert into auth.users(id,email,email_confirmed_at,role,aud) values(identity,'fr33-sql-'||identity||'@example.test',clock_timestamp(),'authenticated','authenticated');
  insert into public.users(email,name,role,verification_status) values('fr33-sql-'||identity||'@example.test','FR33 SQL synthetic',role_name,'approved') returning public.users.id into id;
  perform set_config('fr33.auth_'||who,identity::text,true);perform set_config('fr33.profile_'||who,id::text,true);
  if role_name='rider' then insert into public.riders(userid,is_online,last_seen) values(id,true,clock_timestamp());end if;
 end loop;
end $$;
do $$ declare customer bigint:=current_setting('fr33.profile_customer')::bigint; rider bigint:=current_setting('fr33.profile_rider')::bigint; rider_auth uuid:=current_setting('fr33.auth_rider')::uuid;
 order_id bigint; another bigint; request uuid:=gen_random_uuid(); verification uuid; reserved jsonb; new_reserved jsonb; result jsonb; value text; bad text; role_name text; issuance_count int; begin
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(customer,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into order_id;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 reserved:=public.issue_delivery_otp(order_id,request,rider_auth);value:=reserved->>'otp';
 perform pg_temp.assert(reserved->>'code'='SEND' and value ~ '^[0-9]{6}$','server cryptographic six-digit issuance');
 perform pg_temp.assert((select verifier is not null and nonce is not null and state='RESERVED' from public.delivery_otps where id=request),'only salted protected verifier persisted');
 perform pg_temp.assert(public.issue_delivery_otp(order_id,request,rider_auth)->>'code'='EMAIL_PENDING','same issuance request replay has no new code');
 perform pg_temp.assert(not (public.issue_delivery_otp(order_id,request,rider_auth) ? 'otp'),'replay cannot disclose plaintext');
 perform pg_temp.assert(public.fr33_start_send(request),'provider send claimed once');
 perform pg_temp.assert(not public.fr33_start_send(request),'duplicate dispatch cannot send twice');
 perform pg_temp.assert(public.fr33_finish_send(request,'ACCEPTED','FR33-SQL-MOCK-PROVIDER')->>'code'='EMAIL_ACCEPTED','simulated provider acceptance activates code');
 perform pg_temp.assert((select expires_at-sent_at between interval '599 seconds' and interval '601 seconds' from public.delivery_otps where id=request),'ten-minute accepted issuance lifetime');
 perform pg_temp.assert(public.issue_delivery_otp(order_id,gen_random_uuid(),rider_auth)->>'code'='COOLDOWN','sixty-second cooldown enforced');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',rider_auth,'role','authenticated')::text,true);
 perform pg_temp.assert(public.delivery_otp_status(order_id)->>'code'='EMAIL_ACCEPTED','rider sees safe active status');
 perform pg_temp.assert(not (public.delivery_otp_status(order_id) ?| array['otp','verifier','nonce','recipient']),'public status has no secrets or full recipient');
 bad:=case when value='000000' then '111111' else '000000' end;verification:=gen_random_uuid();
 result:=public.verify_delivery_otp(order_id,bad,verification);perform pg_temp.assert(result->>'code'='INVALID' and result->>'remaining'='2','first wrong code persists two remaining');
 perform pg_temp.assert(public.verify_delivery_otp(order_id,bad,verification)->>'remaining'='2','HTTP verification retry does not consume attempt');
 perform pg_temp.assert(public.verify_delivery_otp(order_id,value,verification)->>'code'='REQUEST_CONFLICT','request identifier cannot change guessed code');
 result:=public.verify_delivery_otp(order_id,bad,gen_random_uuid());perform pg_temp.assert(result->>'remaining'='1','second wrong code persists one remaining');
 result:=public.verify_delivery_otp(order_id,bad,gen_random_uuid());perform pg_temp.assert(result->>'code'='LOCKED' and result->>'remaining'='0','third failure locks without exception rollback');
 perform pg_temp.assert((select attempts=3 and state='LOCKED' from public.delivery_otps where id=request),'lockout persists in database');
 perform pg_temp.assert((select otp_admin_review from public.orders where id=order_id),'third failure flags admin review');
 perform pg_temp.assert((select count(*)=1 from public.notifications where delivery_otp_id=request and type='otp_review'),'exactly one admin lockout notification');
 perform pg_temp.assert((select count(*)=1 from public.security_audit_log where target_id=order_id and action='delivery_otp_locked'),'one lockout audit');
 perform pg_temp.assert(public.verify_delivery_otp(order_id,value,gen_random_uuid())->>'code'='EXPIRED','locked code requires fresh issuance');
 -- Controlled fixture clock movement only inside this rolled-back transaction.
 update public.delivery_otps set created_at=clock_timestamp()-interval '61 seconds' where id=request;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 request:=gen_random_uuid();reserved:=public.issue_delivery_otp(order_id,request,rider_auth);value:=reserved->>'otp';perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'ACCEPTED','FR33-SQL-REPLACEMENT');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',rider_auth,'role','authenticated')::text,true);
 perform pg_temp.assert(public.verify_delivery_otp(order_id,'123',gen_random_uuid())->>'code'='FORMAT','malformed code denied without attempt');
 perform pg_temp.assert((select attempts=0 from public.delivery_otps where id=request),'malformed entry does not consume a guess');
 -- A failed replacement retains the usable old code and its attempt counter.
 update public.delivery_otps set created_at=clock_timestamp()-interval '61 seconds' where id=request;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 new_reserved:=public.issue_delivery_otp(order_id,gen_random_uuid(),rider_auth);perform public.fr33_start_send((new_reserved->>'issuance_id')::uuid);perform public.fr33_finish_send((new_reserved->>'issuance_id')::uuid,'FAILED');
 perform pg_temp.assert((select state='ACCEPTED' and attempts=0 from public.delivery_otps where id=request),'provider failure preserves previous usable OTP');
 foreach role_name in array array['other','customer','vendor','admin'] loop
  perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('fr33.auth_'||role_name),'role','authenticated')::text,true);
  perform pg_temp.assert(public.verify_delivery_otp(order_id,value,gen_random_uuid())->>'code'='FORBIDDEN',role_name||' cannot verify assigned delivery');
  execute 'set local role authenticated';
  perform pg_temp.denied('select * from public.delivery_otps',role_name||' cannot read verifier');
  perform pg_temp.denied(format('select public.issue_delivery_otp(%s,''%s'',''%s'')',order_id,gen_random_uuid(),rider_auth),role_name||' cannot issue server code');
  perform pg_temp.no_update(format('update public.orders set order_status=''delivered'' where id=%s',order_id),role_name||' cannot bypass verification');
  execute 'reset role';
 end loop;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',rider_auth,'role','authenticated')::text,true);
 verification:=gen_random_uuid();result:=public.verify_delivery_otp(order_id,value,verification);
 perform pg_temp.assert(result->>'code'='OK','correct active OTP delivers');
 perform pg_temp.assert((select order_status='delivered' and delivery_otp is null and delivered_at is not null from public.orders where id=order_id),'confirmed status and delivery timestamp preserved');
 perform pg_temp.assert((select count(*)=1 from public.delivery_proof where orderid=order_id::text and otpconfirmed and otp is null),'exactly one compatible protected delivery proof');
 perform pg_temp.assert(public.verify_delivery_otp(order_id,bad,verification)->>'code'='ALREADY_DELIVERED','delivery replay does not reconsume code');
 perform pg_temp.assert((select count(*)=1 from public.security_audit_log where action='delivery_completed' and target_id=order_id),'one completion audit');
 perform pg_temp.assert((select count(*)=1 from public.notifications where delivery_otp_id=request and type='delivery' and message='Your order has been delivered.'),'one exact customer delivery notice');
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(customer,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into another;
 perform pg_temp.assert(public.verify_delivery_otp(another,value,gen_random_uuid())->>'code'='NO_OTP','unissued order cannot deliver');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 request:=gen_random_uuid();reserved:=public.issue_delivery_otp(another,request,rider_auth);perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'ACCEPTED','FR33-SQL-EXPIRY');
 update public.delivery_otps set expires_at=clock_timestamp()-interval '1 second' where id=request;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',rider_auth,'role','authenticated')::text,true);
 perform pg_temp.assert(public.verify_delivery_otp(another,reserved->>'otp',gen_random_uuid())->>'code'='EXPIRED','expired code cannot deliver');
 perform pg_temp.assert((select order_status='on_the_way' from public.orders where id=another),'expiry preserves order state');
 execute 'set local role anon';perform set_config('request.jwt.claims','{"role":"anon"}',true);
 perform pg_temp.denied('select public.verify_delivery_otp(1,''000000'',gen_random_uuid())','anonymous RPC denied');
 perform pg_temp.denied('select * from public.delivery_otps','anonymous verifier read denied');execute 'reset role';
end $$;
do $$ declare case_order bigint; customer bigint:=current_setting('fr33.profile_customer')::bigint; rider bigint:=current_setting('fr33.profile_other')::bigint; identity uuid:=current_setting('fr33.auth_other')::uuid; reservation jsonb; initial jsonb; request uuid; i int; old_code text; fresh_code text; begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(customer,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into case_order;
 initial:=public.issue_delivery_otp(case_order,gen_random_uuid(),identity);old_code:=initial->>'otp';request:=(initial->>'issuance_id')::uuid;perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'ACCEPTED','FR33-SQL-OLD');
 update public.delivery_otps d set created_at=clock_timestamp()-interval '61 seconds' where d.order_id=case_order;
 reservation:=public.issue_delivery_otp(case_order,gen_random_uuid(),identity);request:=(reservation->>'issuance_id')::uuid;perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'UNKNOWN');
 perform pg_temp.assert((select state='ACCEPTED' from public.delivery_otps where id=(initial->>'issuance_id')::uuid),'ambiguous provider timeout retains old active code');
 perform pg_temp.assert(public.issue_delivery_otp(case_order,request,identity)->>'code'='EMAIL_UNKNOWN','timeout replay does not send again');
 update public.delivery_otps d set created_at=clock_timestamp()-interval '61 seconds' where d.order_id=case_order;
 reservation:=public.issue_delivery_otp(case_order,gen_random_uuid(),identity);fresh_code:=reservation->>'otp';request:=(reservation->>'issuance_id')::uuid;perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'ACCEPTED','FR33-SQL-NEW');
 perform pg_temp.assert(old_code<>fresh_code,'replacement never repeats an earlier code');
 perform pg_temp.assert((select count(*)=1 from public.delivery_otps where order_id=case_order and state='ACCEPTED'),'only intended active issuance usable');
 perform pg_temp.assert((select state='INVALIDATED' from public.delivery_otps where id=(initial->>'issuance_id')::uuid),'accepted replacement invalidates predecessor');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',identity,'role','authenticated')::text,true);
 perform pg_temp.assert(public.verify_delivery_otp(case_order,old_code,gen_random_uuid())->>'code'='INVALID','predecessor code cannot verify replacement');
 perform pg_temp.assert(public.verify_delivery_otp(case_order,fresh_code,gen_random_uuid())->>'code'='OK','new code verifies intended issuance');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 update public.delivery_otp_rates set used=0,window_at=clock_timestamp() where rider_id=rider;
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(customer,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into case_order;
 for i in 1..5 loop
  request:=gen_random_uuid();reservation:=public.issue_delivery_otp(case_order,request,identity);
  perform pg_temp.assert(reservation->>'code'='SEND','bounded issuance '||i);
  perform public.fr33_start_send(request);perform public.fr33_finish_send(request,'FAILED');
  update public.delivery_otps d set created_at=clock_timestamp()-interval '61 seconds' where d.order_id=case_order;
 end loop;
 perform pg_temp.assert(public.issue_delivery_otp(case_order,gen_random_uuid(),identity)->>'code'='ISSUANCE_LIMIT','maximum five issuances enforced including failed sends');
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(customer,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into case_order;
 update public.delivery_otp_rates set used=10,window_at=clock_timestamp() where rider_id=rider;
 perform pg_temp.assert(public.issue_delivery_otp(case_order,gen_random_uuid(),identity)->>'code'='RATE_LIMIT','ten new email issuances per rider per minute');
 update public.delivery_otp_rates set used=0,verify_used=100,verify_window=clock_timestamp() where rider_id=rider;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',identity,'role','authenticated')::text,true);
 perform pg_temp.assert(public.verify_delivery_otp(case_order,'000000',gen_random_uuid())->>'code'='RATE_LIMIT','hundred new verification operations per rider per minute');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 update public.delivery_otp_budgets set used=300 where day=(clock_timestamp() at time zone 'UTC')::date;
 perform pg_temp.assert(public.issue_delivery_otp(case_order,gen_random_uuid(),identity)->>'code'='QUOTA_EXCEEDED','daily shared 300-reservation budget enforced');
 update public.orders set order_status='ready' where id=case_order;
 perform pg_temp.assert(public.issue_delivery_otp(case_order,gen_random_uuid(),identity)->>'code'='WRONG_STATE','wrong delivery state cannot issue');
 perform pg_temp.assert(public.issue_delivery_otp(-1,gen_random_uuid(),identity)->>'code'='FORBIDDEN','unknown order does not disclose recipient');
end $$;
do $$ declare target bigint; reservation jsonb; request uuid; identity uuid:=current_setting('fr33.auth_other')::uuid; rider bigint:=current_setting('fr33.profile_other')::bigint; begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 update public.delivery_otp_budgets set used=0;
 update public.delivery_otp_rates set used=0,window_at=clock_timestamp();
 insert into public.orders(user_id,rider_id,order_status,amount,delivery_address) values(current_setting('fr33.profile_customer')::bigint,rider,'on_the_way',25,'FR33 SQL SYNTHETIC ONLY') returning id into target;
 request:=gen_random_uuid();reservation:=public.issue_delivery_otp(target,request,identity);
 update public.delivery_otps set lease_until=clock_timestamp()-interval '1 second' where id=request;
 perform pg_temp.assert(public.issue_delivery_otp(target,request,identity)->>'code'='EMAIL_FAILED','crashed reservation retry resolves to failed, not perpetual pending');
 update public.delivery_otps d set created_at=clock_timestamp()-interval '61 seconds' where d.order_id=target;
 request:=gen_random_uuid();reservation:=public.issue_delivery_otp(target,request,identity);perform public.fr33_start_send(request);
 update public.delivery_otps set lease_until=clock_timestamp()-interval '1 second' where id=request;
 perform pg_temp.assert(public.issue_delivery_otp(target,request,identity)->>'code'='EMAIL_UNKNOWN','crashed in-flight send retry resolves unknown without another send');
 update public.delivery_otps d set created_at=clock_timestamp()-interval '61 seconds' where d.order_id=target;
 request:=gen_random_uuid();reservation:=public.issue_delivery_otp(target,request,identity);
 update public.users set verification_status='pending' where id=rider;
 perform pg_temp.assert(not public.fr33_start_send(request),'rider approval is rechecked at dispatch');
 perform pg_temp.assert((select state='FAILED' from public.delivery_otps where id=request),'revoked dispatch leaves a recoverable failed reservation');
end $$;
select jsonb_agg(jsonb_build_object('test',test,'result',result)) as results from fr33_results;
rollback;
